-- =============================================================================
-- UNIFIED JOURNAL ENTRIES MIGRATION & ATOMIC RPCS (EXACT COLUMNS)
-- ERP System - Production Accounting Standards
-- =============================================================================

-- 1. CREATE CORE JOURNAL & LEDGER TABLES IF NOT EXIST
CREATE TABLE IF NOT EXISTS "public"."journal_entries" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "entry_number" text NOT NULL,
    "entry_date" date DEFAULT CURRENT_DATE NOT NULL,
    "description" text NOT NULL,
    "status" text DEFAULT 'posted'::text NOT NULL,
    "is_auto_generated" boolean DEFAULT true NOT NULL,
    "source_type" text,
    "source_id" text,
    "created_by" uuid,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "posted_at" timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS "public"."account_ledger_entries" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "journal_entry_id" bigint NOT NULL REFERENCES "public"."journal_entries"("id") ON DELETE CASCADE,
    "account_id" bigint NOT NULL,
    "debit" numeric DEFAULT 0 NOT NULL,
    "credit" numeric DEFAULT 0 NOT NULL,
    "currency" text DEFAULT 'EGP'::text NOT NULL,
    "amount_in_base_currency" numeric DEFAULT 0 NOT NULL,
    "description" text,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

-- 2. ADD MISSING COLUMNS AND INDEXES
ALTER TABLE IF EXISTS "public"."account_ledger_entries" 
ADD COLUMN IF NOT EXISTS "amount_in_base_currency" numeric DEFAULT 0 NOT NULL;

ALTER TABLE IF EXISTS "public"."treasury_transactions" 
ADD COLUMN IF NOT EXISTS "journal_entry_id" bigint REFERENCES "public"."journal_entries"("id") ON DELETE SET NULL;

ALTER TABLE IF EXISTS "public"."bank_account_transactions" 
ADD COLUMN IF NOT EXISTS "journal_entry_id" bigint REFERENCES "public"."journal_entries"("id") ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS "idx_treasury_tx_journal_entry_id" ON "public"."treasury_transactions"("journal_entry_id");
CREATE INDEX IF NOT EXISTS "idx_bank_tx_journal_entry_id" ON "public"."bank_account_transactions"("journal_entry_id");
CREATE INDEX IF NOT EXISTS "idx_account_ledger_entries_journal_id" ON "public"."account_ledger_entries"("journal_entry_id");

-- 3. HELPER FUNCTION TO GENERATE ATOMIC SEQUENTIAL ENTRY NUMBER
CREATE OR REPLACE FUNCTION public.fn_generate_journal_entry_number(p_journal_id bigint)
RETURNS text
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN 'JE-' || TO_CHAR(NOW(), 'YYYYMM') || '-' || LPAD(p_journal_id::text, 6, '0');
END;
$$;


-- 4. ATOMIC BANK DEPOSIT RPC
CREATE OR REPLACE FUNCTION public.deposit_bank_account(
    p_bank_account_id bigint,
    p_currency text,
    p_amount numeric,
    p_description text DEFAULT ''::text,
    p_exchange_rate numeric DEFAULT 1.0
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_current_balance NUMERIC := 0;
    v_new_balance NUMERIC := 0;
    v_tx_id BIGINT;
    v_journal_id BIGINT;
    v_entry_num TEXT;
    v_bank_account_id_code BIGINT;
    v_revenue_account_id BIGINT;
    v_amount_base NUMERIC;
    v_sum_debit_base NUMERIC;
    v_sum_credit_base NUMERIC;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    IF p_exchange_rate <= 0 THEN
        p_exchange_rate := 1.0;
    END IF;

    v_amount_base := p_amount * p_exchange_rate;

    SELECT COALESCE(balance, 0) INTO v_current_balance
    FROM bank_accounts WHERE id = p_bank_account_id;

    v_new_balance := v_current_balance + p_amount;

    SELECT id INTO v_bank_account_id_code FROM accounts WHERE account_code = '11201';
    SELECT id INTO v_revenue_account_id FROM accounts WHERE account_code = '41101';

    IF v_bank_account_id_code IS NULL OR v_revenue_account_id IS NULL THEN
        SELECT id INTO v_bank_account_id_code FROM accounts LIMIT 1;
        SELECT id INTO v_revenue_account_id FROM accounts LIMIT 1;
    END IF;

    INSERT INTO journal_entries (
        entry_number, entry_date, description, status, is_auto_generated, source_type, created_by
    ) VALUES (
        'PENDING', CURRENT_DATE, COALESCE(NULLIF(p_description, ''), 'إيداع بنكي مباشر'), 'posted', true, 'bank_deposit', auth.uid()
    ) RETURNING id INTO v_journal_id;

    v_entry_num := fn_generate_journal_entry_number(v_journal_id);
    UPDATE journal_entries SET entry_number = v_entry_num, source_id = v_journal_id::text WHERE id = v_journal_id;

    INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description)
    VALUES (v_journal_id, v_bank_account_id_code, p_amount, 0, p_currency, v_amount_base, p_description);

    INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description)
    VALUES (v_journal_id, v_revenue_account_id, 0, p_amount, p_currency, v_amount_base, p_description);

    SELECT 
        COALESCE(SUM(CASE WHEN debit > 0 THEN amount_in_base_currency ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN credit > 0 THEN amount_in_base_currency ELSE 0 END), 0)
    INTO v_sum_debit_base, v_sum_credit_base
    FROM account_ledger_entries WHERE journal_entry_id = v_journal_id;

    IF v_sum_debit_base <> v_sum_credit_base THEN
        RAISE EXCEPTION 'خطأ محاسبي: القيد غير متوازن بالعملة الأساسية!';
    END IF;

    UPDATE bank_accounts SET balance = v_new_balance WHERE id = p_bank_account_id;

    INSERT INTO bank_account_transactions (
        bank_account_id, type, amount, balance_before, balance_after, description, created_by, journal_entry_id
    ) VALUES (
        p_bank_account_id, 'deposit', p_amount, v_current_balance, v_new_balance, p_description, auth.uid(), v_journal_id
    ) RETURNING id INTO v_tx_id;

    RETURN jsonb_build_object(
        'success', true,
        'transaction_id', v_tx_id,
        'journal_entry_id', v_journal_id,
        'entry_number', v_entry_num,
        'balance_after', v_new_balance
    );
END;
$$;


-- 5. ATOMIC BANK WITHDRAWAL RPC
CREATE OR REPLACE FUNCTION public.withdraw_bank_account(
    p_bank_account_id bigint,
    p_currency text,
    p_amount numeric,
    p_description text DEFAULT ''::text,
    p_exchange_rate numeric DEFAULT 1.0
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_current_balance NUMERIC := 0;
    v_new_balance NUMERIC := 0;
    v_tx_id BIGINT;
    v_journal_id BIGINT;
    v_entry_num TEXT;
    v_bank_account_id_code BIGINT;
    v_expense_account_id BIGINT;
    v_amount_base NUMERIC;
    v_sum_debit_base NUMERIC;
    v_sum_credit_base NUMERIC;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'المبلغ يجب أن يكون أكبر من صفر';
    END IF;

    IF p_exchange_rate <= 0 THEN
        p_exchange_rate := 1.0;
    END IF;

    v_amount_base := p_amount * p_exchange_rate;

    SELECT COALESCE(balance, 0) INTO v_current_balance
    FROM bank_accounts WHERE id = p_bank_account_id;

    IF v_current_balance < p_amount THEN
        RAISE EXCEPTION 'الرصيد البنكي غير كافٍ في % (المتوفر: %)', p_currency, v_current_balance;
    END IF;

    v_new_balance := v_current_balance - p_amount;

    SELECT id INTO v_bank_account_id_code FROM accounts WHERE account_code = '11201';
    SELECT id INTO v_expense_account_id FROM accounts WHERE account_code = '51101';

    IF v_bank_account_id_code IS NULL OR v_expense_account_id IS NULL THEN
        SELECT id INTO v_bank_account_id_code FROM accounts LIMIT 1;
        SELECT id INTO v_expense_account_id FROM accounts LIMIT 1;
    END IF;

    INSERT INTO journal_entries (
        entry_number, entry_date, description, status, is_auto_generated, source_type, created_by
    ) VALUES (
        'PENDING', CURRENT_DATE, COALESCE(NULLIF(p_description, ''), 'سحب / مصروف بنكي مباشر'), 'posted', true, 'bank_withdraw', auth.uid()
    ) RETURNING id INTO v_journal_id;

    v_entry_num := fn_generate_journal_entry_number(v_journal_id);
    UPDATE journal_entries SET entry_number = v_entry_num, source_id = v_journal_id::text WHERE id = v_journal_id;

    INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description)
    VALUES (v_journal_id, v_expense_account_id, p_amount, 0, p_currency, v_amount_base, p_description);

    INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description)
    VALUES (v_journal_id, v_bank_account_id_code, 0, p_amount, p_currency, v_amount_base, p_description);

    SELECT 
        COALESCE(SUM(CASE WHEN debit > 0 THEN amount_in_base_currency ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN credit > 0 THEN amount_in_base_currency ELSE 0 END), 0)
    INTO v_sum_debit_base, v_sum_credit_base
    FROM account_ledger_entries WHERE journal_entry_id = v_journal_id;

    IF v_sum_debit_base <> v_sum_credit_base THEN
        RAISE EXCEPTION 'خطأ محاسبي: القيد غير متوازن بالعملة الأساسية!';
    END IF;

    UPDATE bank_accounts SET balance = v_new_balance WHERE id = p_bank_account_id;

    INSERT INTO bank_account_transactions (
        bank_account_id, type, amount, balance_before, balance_after, description, created_by, journal_entry_id
    ) VALUES (
        p_bank_account_id, 'withdrawal', p_amount, v_current_balance, v_new_balance, p_description, auth.uid(), v_journal_id
    ) RETURNING id INTO v_tx_id;

    RETURN jsonb_build_object(
        'success', true,
        'transaction_id', v_tx_id,
        'journal_entry_id', v_journal_id,
        'entry_number', v_entry_num,
        'balance_after', v_new_balance
    );
END;
$$;
